SELECT toStartOfMonth(created_at) AS month,countIf(event_type='PushEvent') AS pushes,countIf(event_type='PullRequestEvent') AS pull_request_events,countIf(event_type='PullRequestEvent' AND action='opened') AS opened_pull_requests,countIf(event_type='PullRequestEvent' AND action='none') AS missing_pr_actions FROM github_events WHERE event_type IN ('PushEvent','PullRequestEvent') AND toYear(created_at) BETWEEN 2023 AND 2026 AND created_at<'2026-10-26 21:00:00' AND file_time<'2026-10-26 21:00:00' GROUP BY month ORDER BY month SETTINGS max_execution_time=60 FORMAT JSON
